/**
 * Side-effect CSS imports bundled by esbuild (Swiper view scripts).
 */
declare module 'swiper/css' {
	const css: string;
	export default css;
}

declare module 'swiper/css/navigation' {
	const css: string;
	export default css;
}

declare module 'swiper/css/pagination' {
	const css: string;
	export default css;
}
